/**
 * work-order.model.js
 *
 * Mongoose schema for Work Orders.
 * Generated by admins from approved maintenance requests or complaints.
 * Assigned to maintenance staff within the same apartment.
 */

import mongoose from 'mongoose';

// ── Subdocument: Progress History ─────────────────────────────────────────────
const progressSchema = new mongoose.Schema(
  {
    changedBy: {
      type: mongoose.Schema.Types.ObjectId,
      ref: 'User',
      default: null,
    },
    changedByName: { type: String, trim: true, default: '' },
    changedByRole: { type: String, trim: true, default: '' },
    fromStatus: { type: String, trim: true, default: null },
    toStatus: { type: String, trim: true, default: null },
    note: { type: String, trim: true, default: '' },
  },
  { timestamps: true },
);

// ── Main Work Order Schema ─────────────────────────────────────────────────────
const workOrderSchema = new mongoose.Schema(
  {
    // Human-readable identifier
    orderNumber: {
      type: String,
      unique: true,
      sparse: true,
    },

    // Source reference — exactly one should be populated
    complaintId: {
      type: mongoose.Schema.Types.ObjectId,
      ref: 'Complaint',
      default: null,
      index: true,
    },

    // Multi-tenant scoping
    apartmentId: {
      type: mongoose.Schema.Types.ObjectId,
      ref: 'Apartment',
      required: [true, 'Apartment association is required.'],
      index: true,
    },
    buildingId: {
      type: mongoose.Schema.Types.ObjectId,
      ref: 'Building',
      default: null,
    },
    flatId: {
      type: mongoose.Schema.Types.ObjectId,
      ref: 'Flat',
      default: null,
    },

    // Content
    title: {
      type: String,
      required: [true, 'Work order title is required.'],
      trim: true,
      maxlength: [200, 'Title cannot exceed 200 characters.'],
    },
    description: {
      type: String,
      trim: true,
      default: '',
      maxlength: [5000, 'Description cannot exceed 5000 characters.'],
    },
    category: {
      type: String,
      lowercase: true,
      trim: true,
      enum: {
        values: [
          'plumbing',
          'electrical',
          'cleaning',
          'security',
          'pest_control',
          'appliance',
          'hvac',
          'structural',
          'other',
        ],
        message: '{VALUE} is not a valid category.',
      },
      default: 'other',
    },
    priority: {
      type: String,
      lowercase: true,
      trim: true,
      enum: {
        values: ['low', 'medium', 'high', 'urgent'],
        message: '{VALUE} is not a valid priority.',
      },
      default: 'medium',
    },
    status: {
      type: String,
      lowercase: true,
      trim: true,
      enum: {
        values: ['pending', 'in_progress', 'resolved', 'closed', 'cancelled'],
        message: '{VALUE} is not a valid status.',
      },
      default: 'pending',
      index: true,
    },

    // People
    createdBy: {
      type: mongoose.Schema.Types.ObjectId,
      ref: 'User',
      required: [true, 'Creator reference is required.'],
    },
    assignedTo: {
      type: mongoose.Schema.Types.ObjectId,
      ref: 'User',
      default: null,
      index: true,
    },

    // Scheduling
    dueDate: {
      type: Date,
      default: null,
    },

    // Completion
    completionNotes: {
      type: String,
      trim: true,
      default: '',
    },
    completedAt: {
      type: Date,
      default: null,
    },

    progressHistory: [progressSchema],
  },
  {
    timestamps: true,
    toJSON: { virtuals: true },
    toObject: { virtuals: true },
  },
);

// ── Auto-generate order number before first save ──────────────────────────────
workOrderSchema.pre('save', async function () {
  if (!this.orderNumber) {
    const count = await mongoose.models.WorkOrder.countDocuments();
    this.orderNumber = `WO-${String(count + 1).padStart(5, '0')}`;
  }
});

// ── Indexes ───────────────────────────────────────────────────────────────────
workOrderSchema.index({ apartmentId: 1, status: 1 });
workOrderSchema.index({ apartmentId: 1, assignedTo: 1 });
workOrderSchema.index({ apartmentId: 1, createdAt: -1 });
// Prevent duplicate work orders from the same source complaint
workOrderSchema.index(
  { complaintId: 1 },
  { unique: true, sparse: true, name: 'unique_work_order_per_complaint' },
);

const WorkOrder =
  mongoose.models.WorkOrder || mongoose.model('WorkOrder', workOrderSchema);

export default WorkOrder;
